#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7

# 固定事实（单一来源：worker/wrangler.jsonc / README / ADR 0008 / 迁移文件头）
local SITE_DB="blog-db"
local DB_ID="5c759ce7-82e0-4205-8d01-fea18db55cd7"
local D1_URL="https://dash.cloudflare.com/?to=/:account/workers/d1/database/5c759ce7-82e0-4205-8d01-fea18db55cd7"
local WIZARD_ROOT
WIZARD_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
local MIGRATION_FILE="$WIZARD_ROOT/worker/schema-tag-category-incremental.sql"

# 审计 SQL 与迁移文件第 48–80 行同源；演练与生产核对两阶段都打印它。
local AUDIT_SQL
AUDIT_SQL=$(cat <<'SQL'
-- 审计 1：null category 必须为 0（= 0 才算迁移成功）
SELECT COUNT(*) AS null_category_tags
FROM tags
WHERE category_id IS NULL;

-- 审计 2：跨分类标签清单（文章分类 ≠ 所挂标签的归属；供 #82 人工整理）
SELECT a.category_id AS article_category,
       c1.name       AS article_category_name,
       t.id          AS tag_id,
       t.name        AS tag_name,
       t.category_id AS tag_category,
       c2.name       AS tag_category_name,
       COUNT(*)      AS usage_count
FROM article_tags at
JOIN articles a ON at.article_id = a.id
JOIN tags t ON at.tag_id = t.id
LEFT JOIN categories c1 ON c1.id = a.category_id
LEFT JOIN categories c2 ON c2.id = t.category_id
WHERE a.category_id IS NOT NULL
  AND t.category_id IS NOT NULL
  AND a.category_id != t.category_id
GROUP BY a.category_id, t.id
ORDER BY usage_count DESC, t.id ASC;

-- 审计 3：各分类标签数（迁移后的分布快照）
SELECT c.id   AS category_id,
       c.name AS category_name,
       COUNT(t.id) AS tag_count
FROM categories c
LEFT JOIN tags t ON t.category_id = c.id
GROUP BY c.id
ORDER BY tag_count DESC, c.id ASC;
SQL
)

banner "Taxonomy v2 — one-off D1 migration (tags.category_id)"

# ── Stage 1：前置确认 ────────────────────────────────────────────────────
stage "Preflight — understand the boundaries"
say "This wizard walks the ONE-TIME taxonomy v2 migration: tags.category_id."
say "Scope: add column + index + 'uncategorized' seed + deterministic backfill."
warn "The migration file has a bare ALTER TABLE ADD COLUMN (no IF NOT EXISTS)."
warn "Running it twice fails with 'duplicate column name: category_id'. Once only."
say "Fresh installs DO NOT need this file: schema.sql already has the column."
say "This is a structural migration: it stays OUT of the CI replay net."
say "Order matters: migrate FIRST, deploy code AFTER (else the read API sees no column)."
if command -v npx >/dev/null 2>&1; then say "npx: found."; else warn "npx not found — install Node/npm before the production stage."; fi
if [[ -f "$MIGRATION_FILE" ]]; then say "migration file: found ($MIGRATION_FILE)."; else warn "migration file MISSING: $MIGRATION_FILE"; fi
if confirm "Understood the risks and want to continue?"; then say "Let's go."; else warn "Stopped at preflight. Nothing was changed."; return 0; fi

# ── Stage 2：备份（Time Travel + 逐表 dump）──────────────────────────────
stage "Backup — Time Travel restore point + per-table dump"
say "wrangler d1 export is UNUSABLE on this DB (FTS5 virtual tables)."
say "Back up via two independent means: a Time Travel point AND per-table JSON dumps."
open_url "$D1_URL"
step "In D1 database '$SITE_DB' ($DB_ID), open the 'Time Travel' / Backups view."
step "Note a restore point timestamp from BEFORE the migration (copy it exactly)."
ask RESTORE_POINT "Paste the restore point timestamp/label:"
write_env RESTORE_POINT "$RESTORE_POINT"
step "Choose a local backup directory, then run the dump commands below (from repo root)."
ask BACKUP_DIR "Backup directory (e.g. ./backup-taxonomy-2026-11-17):"
write_env BACKUP_DIR "$BACKUP_DIR"
say "Per-table dump commands (copy/paste from repo root):"
cat <<EOF
  mkdir -p "$BACKUP_DIR"
  for t in users categories tags articles article_tags comments article_likes media_assets friend_links site_config analytics_article_daily analytics_view_token analytics_dim_daily; do
    npx wrangler d1 execute $SITE_DB --remote --json --config=worker/wrangler.jsonc \\
      --command="SELECT * FROM \$t;" > "$BACKUP_DIR/\$t.json"
  done
EOF
note "The dump uses --json because d1 export can't handle FTS5 here."
if confirm "Restore point noted AND per-table dumps saved?"; then say "Backup recorded."; else warn "Backup not confirmed — do NOT continue to production."; SKIPPED+=("backup not confirmed"); fi

# ── Stage 3：副本演练 ────────────────────────────────────────────────────
stage "Rehearse on a copy — never on production"
say "Restore a COPY from the dump above (local SQLite file or a scratch D1 DB)."
say "Prepare the copy by any means you trust (sqlite3, or a throwaway DB + the dump)."
note "If you need the exact restore path, convert the per-table JSON dumps back to INSERTs, or use /admin/export + /admin/import on a scratch environment."
say "Then run the migration file against the COPY only:"
cat <<EOF
  npx wrangler d1 execute <COPY_DB> --local --config=worker/wrangler.jsonc \\
    --file=./worker/schema-tag-category-incremental.sql
  # or, for a local sqlite copy:
  sqlite3 <COPY.sqlite> < worker/schema-tag-category-incremental.sql
EOF
say "Then run these three audit SQLs on the COPY:"
printf '%s\n' "$AUDIT_SQL"
pause "Rehearsal run finished? Press Enter to confirm the gates."

# ── Stage 4：演练三关 ────────────────────────────────────────────────────
stage "Rehearsal gates — all three must pass"
say "Gate 1: row counts unchanged (tags / articles / article_tags)."
say "Gate 2: audit 1 returns null_category_tags = 0."
say "Gate 3: audit 2 produces the cross-category list (may be empty, but must run)."
note "Expected snapshot from the 2026-11-17 audit: categories=4 tags=1 articles=3 article_tags=1, null=0, cross-category=0."
if confirm "All three gates passed on the COPY?"; then say "Rehearsal passed."; else warn " rehearsal failed — STOP. Fix before touching production."; SKIPPED+=("rehearsal gates not passed"); return 0; fi

# ── Stage 5：生产执行（confirm 后脚本代跑）───────────────────────────────
stage "Production execute — one irreversible command"
warn "This runs against LIVE production D1 ($SITE_DB / $DB_ID)."
say "Command to be executed:"
say "  cd worker && npx wrangler d1 execute $SITE_DB --remote --yes \\"
say "    --config=wrangler.jsonc --file=./schema-tag-category-incremental.sql"
if [[ -n "${CLOUDFLARE_API_TOKEN:-}" ]]; then say "Auth: CLOUDFLARE_API_TOKEN from environment."
elif (cd "$WIZARD_ROOT/worker" && npx wrangler whoami >/dev/null 2>&1); then say "Auth: wrangler OAuth login detected."
else warn "No wrangler auth detected — the command below will likely fail. Log in first (npx wrangler login) or set CLOUDFLARE_API_TOKEN."; fi
if confirm "TYPE y to run the production migration NOW?"; then
  if (cd "$WIZARD_ROOT/worker" && npx wrangler d1 execute "$SITE_DB" --remote --yes --config=wrangler.jsonc --file=./schema-tag-category-incremental.sql); then
    say "Migration command returned 0. Verify in the next stage."
  else
    warn "Migration FAILED. Do NOT blindly retry (duplicate column risk)."
    warn "Decide: rollback via the Time Travel point ($RESTORE_POINT) / dump, or fix by hand."
    SKIPPED+=("production migration failed — rollback vs manual fix needed")
  fi
else
  warn "Production execution skipped. Re-run the wizard when ready."
  SKIPPED+=("production migration not executed")
fi

# ── Stage 6：生产审计核对 ────────────────────────────────────────────────
stage "Production audit — confirm the landed state"
say "Run these three audit SQLs on production (Dashboard D1 console or wrangler):"
printf '%s\n' "$AUDIT_SQL"
step "Gate 1: null_category_tags = 0. Gate 2: cross-category list reviewed. Gate 3: distribution snapshot saved."
if confirm "Production audit looks correct?"; then say "Production state confirmed."; else warn "Audit mismatch — investigate before deploying code."; SKIPPED+=("production audit not confirmed"); fi

# ── Stage 7：部署与回滚 ──────────────────────────────────────────────────
stage "Deploy code & remember rollback"
say "Migration is done — NOW push/deploy the taxonomy v2 code (migrate first, deploy second)."
say "Local gates before push: PW_CHANNEL=msedge node scripts/verify-article-ssr.mjs && node scripts/verify-all-pages-nav.mjs."
say "Rollback (ADR 0008): revert CODE only, leave the column in place. Restore data from the restore point ($RESTORE_POINT) / dump if needed."
warn "Never DROP COLUMN in an incident (SQLite rebuild + live writes = second outage)."
say "Strict validation (site_config.strict_tag_category_validation) stays OFF by default; enable by hand only if #82 decides."
finish
}

run_wizard "$@"; exit
